var targetUrl = base + pathAndQuery;

var res = request(targetUrl, {
    headers: { 'Accept': 'application/json' }
});

if (!res) {
    throw new Error('Bridge /video_list returned empty response for ' + targetUrl);
}

var json = typeof res === 'string' ? JSON.parse(res) : res;
if (json && json.ok === false) {
    var errMsg = (json.error && json.error.message) ? json.error.message : 'Bridge error';
    throw new Error(errMsg);
}

var list = (json && json.items) || (json && json.data && json.data.items) || [];
if (!Array.isArray(list)) {
    throw new Error('Expected items array but got: ' + typeof list);
