        var lazyScript = '.js:(() => {' +
            'var base = (typeof MY_PARAMS !== \"undefined\" && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : \"http://127.0.0.1:18002\";' +
            'while (base.length > 0 && base.charAt(base.length - 1) === \"/\") { base = base.substring(0, base.length - 1); }' +
            'var p = input.indexOf(\"/\", 8);' +
            'var reqUrl = (p !== -1) ? (base + input.substring(p)) : input;' +
            'var r = request(reqUrl, { headers: { \"Accept\": \"application/json\" } });' +
            'if (!r) throw new Error(\"Empty response from bridge /play\");' +
            'var j = typeof r === \"string\" ? JSON.parse(r) : r;' +
            'if (j && j.ok === false) throw new Error((j.error && j.error.message) ? j.error.message : \"Play resolve failed\");' +
            'var dat = j.data || j;' +
            'var def = dat.default || 0;' +
            'var list = dat.list || [];' +
            'if (!list.length) throw new Error(\"No play variants returned\");' +
            'var v = list[def] || list[0];' +
            'var mUrl = v.url;' +
            'var hdrs = v.headers || {};' +
            'var hArr = [];' +
            'for (var k in hdrs) { if (hdrs.hasOwnProperty(k)) hArr.push(k + \"@\" + hdrs[k]); }' +
            'if (hArr.length > 0) return mUrl + \";{\" + hArr.join(\"&&\") + \"}\";' +
            'return mUrl;' +
        '})()';

        d.push({
            title: epName,
            url: playEndpoint + '@lazyRule=' + lazyScript,
            col_type: 'text_3'
        });
    }
}
setResult(d);"""

